#!/usr/bin/env bash
# Regenerate the product's CLI reference pages before the docs sync copies them.
#
# The pages in a blowhorn checkout's docs/reference/cli/ (and the
# command table in docs/reference/cli.md) are generated by the product's
# release/scripts/cli_reference/build.py from its CLI schema and parser.
# Running it here, at the ref being synced, means a page that was not
# regenerated before its commit can never be published stale. A ref from
# before the generator existed keeps the pages it has.
#
# Usage: docs-cli-reference.sh [SOURCE_DIR]  (default: product)
#
# PYTHON (default python3) needs typer and PyYAML; sync-docs.yml installs them.
set -euo pipefail
source_dir="${1:-product}"
python="${PYTHON:-python3}"
build="$source_dir/release/scripts/cli_reference/build.py"
if [ ! -f "$build" ]; then
  echo "docs-cli-reference: no $build at this ref; syncing the pages it has"
  exit 0
fi
exec "$python" "$build"
